(() => {
  const T = window.__three
  const st = window.__store.getState()
  const cam = T.camera
  const el = T.gl.domElement
  const W = el.clientWidth, H = el.clientHeight
  const rc = T.raycaster
  const V2 = new (T.scene.position.constructor === undefined ? Object : Object)()
  const STEP = 12
  const visible = (o) => { let p = o; while (p) { if (!p.visible) return false; p = p.parent } return true }
  // A FADED WALL fragment: a transparent, mid-opacity mesh built from the wall body's
  // ExtrudeGeometry. During a reveal fade every wall OVERLAY (face plane, trim, section cap) is
  // hidden (WALL-FADE-OVERLAY-CULL), so the extruded body is the only wall mesh drawn — which
  // makes the geometry type an exact discriminator against the door leaves / window glass that
  // fade with their host wall.
  const isFadedWall = (o) => {
    if (!o.isMesh || !visible(o)) return false
    if (!o.geometry || o.geometry.type !== 'ExtrudeGeometry') return false
    const ms = Array.isArray(o.material) ? o.material : [o.material]
    const m = ms[0]
    return !!m && m.transparent === true && m.opacity > 0.02 && m.opacity < 0.985
  }
  const geomCensus = {}
  T.scene.traverse((o) => {
    if (!o.isMesh || !visible(o)) return
    const ms = Array.isArray(o.material) ? o.material : [o.material]
    const m = ms[0]
    if (!m || !m.transparent || m.opacity >= 0.985 || m.opacity <= 0.02) return
    const k = o.geometry ? o.geometry.type : 'none'
    geomCensus[k] = (geomCensus[k] || 0) + 1
  })
  const stacked = [], single = []
  let rays = 0
  for (let y = 6; y < H; y += STEP) {
    for (let x = 6; x < W; x += STEP) {
      rays++
      rc.setFromCamera({ x: (x / W) * 2 - 1, y: -(y / H) * 2 + 1 }, cam)
      const hits = rc.intersectObjects(T.scene.children, true)
      let n = 0
      const seen = new Set()
      for (const h of hits) {
        const o = h.object
        if (!visible(o)) continue
        const ms = Array.isArray(o.material) ? o.material : [o.material]
        const m = ms[0]
        if (!m) continue
        if (m.colorWrite === false) continue
        if (isFadedWall(o)) { if (!seen.has(o.id)) { seen.add(o.id); n++ } ; continue }
        if (m.transparent === true && m.opacity < 0.985) continue // other translucent: keep going
        break // first OPAQUE surface ends the count
      }
      if (n >= 2) stacked.push([x, y])
      else if (n === 1) single.push([x, y])
    }
  }
  window.__sl = window.__sl || []
  window.__sl.push({
    head: { pose: "05-close-living-corner", flag: st.featureFlags.wallRevealSingleLayer,
      w: W, h: H, step: STEP, rays, stackedPx: stacked.length, singlePx: single.length, geomCensus },
    stacked, single,
  })
})()

